-- Inventário geral de 18/10/2026 (antes do início da produção; planilha oficial de 19/10/2026), aplicado em 26/10/2026.
-- Produto acabado: contagem em 18/10 00:00 (estoque = contagem + produção lançada depois − cargas carregadas depois).
-- Matéria-prima: contagem em 18/10 00:00 (saldo = contagem + recebimentos − perdas − consumo das OPs concluídas depois).
-- A cola da rotuladora passou a ser contada em kg. Garrafões (módulo): contagem 10L, 20L e 20L rosca e acerto da sucata.
begin;
update docs set data = data || '{"unidade": "kg", "atualizadoEm": "2026-10-26T16:30:00.000Z"}'::jsonb, atualizado_em = now() where colecao='mp-insumos' and id='ins-cola-rotulo';
on conflict do nothing;
commit;
